import{j as e}from"./index-BJEF3AA0.js";import{S as t}from"./ServicePageLayout-DjWDAuGa.js";import{M as a}from"./message-square-b4E_iZh3.js";import"./button-Cw0xvSQk.js";import"./PageBanner-BA44tIJw.js";import"./Breadcrumbs-DFM23V6R.js";import"./chevron-right-lYK8hZ14.js";function c(){return e.jsx(t,{"code-path":"src\\pages\\services\\BulkSMS.tsx:6:5",title:"Bulk SMS",subtitle:"Reach every Kenyan customer in seconds",description:"MobiWave is a Kenyan bulk SMS provider with direct interconnects to Safaricom, Airtel and Telkom. Send transactional alerts, OTPs, marketing campaigns and two-way customer conversations from one REST API and one dashboard — with 99.9% delivery, transparent KES pricing, and no grey-route surprises.",icon:a,stats:[{value:"99.9%",label:"Delivery Rate"},{value:"<2s",label:"Avg. Delivery Time"},{value:"3",label:"Kenya Networks"},{value:"0",label:"Setup Fee"}],features:["Direct interconnect with Safaricom, Airtel and Telkom — no grey routes","Personalised sender ID on all three Kenyan networks","Real-time delivery reports with per-MSISDN status","Message scheduling and recurring campaigns","REST API + SDKs (Node.js, PHP, Python, cURL)","Two-way SMS and shortcode for surveys and support","Sandbox environment with test numbers","Per-MSISDN opt-in ledger for ODPC compliance","Automatic 07:00–19:00 CAK promotional window enforcement","Webhook callbacks for every delivery event"],benefits:["Deliver to all Kenyan mobile subscribers — Safaricom, Airtel and Telkom — from one account","Transparent KES pricing starting at KES 0.20 per SMS at volume, with no setup or admin fees","Native M-Pesa STK Push integration for one-tap payment collection in the same flow","CAK-aligned sender ID registration handled during onboarding at no extra cost","24/7 local Nairobi support via phone, email and WhatsApp","SLA-backed 99.9% delivery on transactional traffic"],useCases:[{title:"Marketing campaigns",description:"Promote products, sales and seasonal offers to segmented audiences with personalised sender ID and delivery analytics."},{title:"OTPs and verification",description:"Power two-factor authentication and account verification with low-latency, high-priority delivery on Safaricom, Airtel and Telkom."},{title:"Appointment and payment reminders",description:"Reduce no-shows and improve collections with automated SMS reminders triggered from your CRM or booking system."},{title:"M-Pesa receipts and notifications",description:"Send instant C2B confirmations, B2C payout alerts and account notifications via Daraja webhooks straight to your customer."},{title:"Emergency alerts",description:"Broadcast critical updates — service outages, security warnings, weather alerts — to thousands of subscribers in under a minute."},{title:"Customer engagement and loyalty",description:"Run two-way surveys, NPS collection and loyalty programs using shortcodes with shared or dedicated numbers."},{title:"School and SACCO communications",description:"Send fee reminders, results slips, meeting notices and contribution statements to parents and SACCO members."},{title:"Government and NGO outreach",description:"Reach citizens and beneficiaries with health campaigns, voter education and field-worker dispatches — works on every phone, including feature phones."}],howItWorks:[{step:"1",title:"Sign up and verify your business",description:"Register with your Kenyan business registration, KRA PIN and a contact at +254 736 427 842. We verify and activate your account within one business day."},{step:"2",title:"Register your sender ID on all three networks",description:"We handle CAK-aligned Sender ID registration with Safaricom, Airtel and Telkom on your behalf at no extra admin fee. Most sender IDs are approved in 1–3 business days."},{step:"3",title:"Test in the sandbox",description:"Use our sandbox to send test SMS to approved test numbers, validate webhooks, and verify your templates. Switch to production keys when you are ready."},{step:"4",title:"Send your first campaign",description:"Send via REST API, our web dashboard, or scheduled recurring triggers. Watch delivery status stream in real time to a webhook or our reporting dashboard."},{step:"5",title:"Scale with volume pricing",description:"As monthly volume grows, your per-SMS rate steps down automatically across our tiered plans. Enterprise customers get a dedicated account manager and 24/7 priority support."},{step:"6",title:"Bundle with M-Pesa, WhatsApp and USSD",description:"Add native M-Pesa STK Push, WhatsApp Business API, USSD menus or airtime rewards from the same MobiWave account — one billing line, one support contact."}],comparisonTable:{headers:["MobiWave","Africa's Talking","Celcom Africa","Twilio"],note:"Pricing reflects publicly listed Kenya rates as of August 2026. Volume and contract discounts available on request.",rows:[{name:"Promotional SMS (Safaricom)",cells:[{text:"KES 0.25",highlight:!0},{text:"KES 0.40"},{text:"KES 0.40"},{text:"~KES 5.85"}]},{name:"Transactional SMS (Safaricom)",cells:[{text:"KES 0.30",highlight:!0},{text:"KES 0.60"},{text:"KES 0.60"},{text:"~KES 5.85"}]},{name:"Sender ID registration",cells:[{text:"Free, handled for you",highlight:!0},{text:"KES 7,000 per network"},{text:"KES 7,000 per network"},{text:"Via international aggregator"}]},{name:"M-Pesa STK Push",cells:[{text:"Native, bundled",highlight:!0},{text:"Add-on"},{text:"Add-on"},{text:"Not native"}]},{name:"WhatsApp Business API",cells:[{text:"Yes",highlight:!0},{text:"Yes"},{text:"Yes (reseller)"},{text:"Yes"}]},{name:"USSD shortcodes",cells:[{text:"Shared + dedicated",highlight:!0},{text:"Shared only"},{text:"Shared + dedicated"},{text:"Not supported"}]},{name:"Airtime rewards / bulk airtime",cells:[{text:"Bundled",highlight:!0},{text:"Yes"},{text:"Yes"},{text:"Yes"}]},{name:"SMS surveys (two-way)",cells:[{text:"Included",highlight:!0},{text:"Add-on"},{text:"Add-on"},{text:"Add-on"}]},{name:"Local Kenya support",cells:[{text:"24/7 phone + WhatsApp",highlight:!0},{text:"Developer-only"},{text:"Business hours"},{text:"No local team"}]},{name:"Sandbox + SDKs",cells:[{text:"Yes (Node, PHP, Python)",highlight:!0},{text:"Yes (broadest SDK coverage)"},{text:"Yes"},{text:"Yes (global standard)"}]}]},pricing:[{title:"Small Business",price:"KES 0.35",unit:"/SMS",features:["1 – 50,000 SMS per month","Personalised sender ID on all three networks","Real-time delivery reports","Web dashboard + REST API","24/7 support"]},{title:"Medium Business",price:"KES 0.30",unit:"/SMS",features:["50,001 – 500,000 SMS per month","Everything in Small Business","Message scheduling + recurring campaigns","Webhook callbacks","24/7 priority support"]},{title:"Large Business",price:"KES 0.25",unit:"/SMS",features:["500,001 – 2,000,000 SMS per month","Everything in Medium Business","Two-way SMS + shortcode","M-Pesa STK Push integration","Dedicated account manager"]},{title:"Enterprise",price:"KES 0.20",unit:"/SMS",features:["Above 2,000,000 SMS per month","Everything in Large Business","Custom SLAs and throughput guarantees","On-premise or private-cloud option","24/7 priority support + named engineer","Custom integrations and onboarding"]}],faqs:[{question:"How much does bulk SMS cost in Kenya in 2026?",answer:"MobiWave charges from KES 0.20 to KES 0.35 per SMS depending on monthly volume. The Small Business tier (1–50,000 SMS/month) is KES 0.35, Medium (50,001–500,000) is KES 0.30, Large (500,001–2M) is KES 0.25, and Enterprise (2M+) is KES 0.20. Pricing is per-network and inclusive of sender ID registration. There are no setup fees and no admin fees."},{question:"How long does sender ID registration take?",answer:"Sender ID registration with Safaricom, Airtel and Telkom is handled by MobiWave during onboarding at no extra cost. Most sender IDs are approved within 1–3 business days. A separate transactional and promotional sender ID is required for Safaricom, and we register both for you. You will need a signed and stamped authorisation letter on your company letterhead."},{question:"Do you support M-Pesa STK Push?",answer:"Yes. Native M-Pesa STK Push, C2B confirmations, B2C payouts and B2B transfers are supported out of the box — not via a third-party middleman. You can trigger STK Push from your checkout, CRM or USSD flow in the same MobiWave account, with automatic reconciliation against incoming payments."},{question:"What is your delivery rate?",answer:"We deliver 99.9% of transactional SMS on Safaricom, Airtel and Telkom, with average end-to-end delivery under 2 seconds. Real-time delivery reports are available per MSISDN via our dashboard and webhook callbacks, so you always know who received your message and who did not."},{question:"Is MobiWave CAK and ODPC compliant?",answer:"Yes. MobiWave routes SMS over direct carrier interconnects and registers sender IDs through the Communications Authority of Kenya (CAK) framework. We maintain a per-MSISDN opt-in ledger with audit export for the Office of the Data Protection Commissioner (ODPC), and we enforce the 07:00–19:00 promotional window by default to keep you within CAK advertising rules."},{question:"Can I send SMS via an API?",answer:"Yes. Our REST API accepts a single recipient or an array of up to 1,000 recipients per call. SDKs are available for Node.js, PHP, Python and cURL. A sandbox with approved test numbers lets you validate webhooks and templates before going live, and you can switch from sandbox to production keys without code changes."},{question:"How is MobiWave different from Africa’s Talking or Celcom Africa?",answer:"MobiWave bundles bulk SMS, M-Pesa STK Push, WhatsApp Business API, USSD shortcodes, bulk airtime and SMS surveys on one Kenyan billing line with 24/7 local support. Africa’s Talking is developer-focused and works well for raw APIs, while Celcom Africa is strong for marketing-only bulk sends. We sit between both — full API depth plus managed onboarding for non-developer teams."},{question:"Can I schedule messages and run recurring campaigns?",answer:"Yes. Schedule a one-off send for a specific date and time, or set up recurring campaigns (daily, weekly, monthly) with templates and merge fields. You can also trigger transactional messages from your application via our REST API with millisecond latency."},{question:"Do you support two-way SMS and surveys?",answer:"Yes. MobiWave provides two-way SMS over shortcodes with webhook callbacks for every inbound message. This powers SMS surveys, customer support lines, voting and opt-in flows. Shared shortcodes are available immediately; dedicated shortcodes are provisioned within 2–4 weeks through CAK."},{question:"What happens if delivery fails?",answer:"Failed messages are automatically retried on alternate routes within the carrier interconnect. You are billed only for successfully delivered SMS — failed deliveries are credited back to your account automatically, and you can download a CSV of every delivery attempt from the dashboard."}]})}export{c as BulkSMS};
